];

function mapearTag(rawTag) {
  const n = norm(rawTag);
  for (const t of TAG_MAP) {
    if (n === t.name) return t.id;
  }
  for (const t of TAG_MAP) {
    if (t.kw.some(k => n.includes(k))) return t.id;
  }
  return null;
}

function resolverTagIds(tagsRaw) {
  if (!tagsRaw || !String(tagsRaw).trim()) return [];
  const partes = String(tagsRaw).split(/[,\/;]|\se\s/i).map(t => t.trim()).filter(Boolean);
  const resolved = new Set();
  for (const parte of partes) {
    const id = mapearTag(parte);
    if (id) resolved.add(id);
    else console.log('Tag nao mapeada: "' + parte + '"');
  }
  return [...resolved];
}

const row = $input.item.json;

let telefone = String(row['Telefone comercial (contato)'] || '').replace(/\D/g, '');
if (telefone.startsWith('55') && telefone.length === 13) {
  telefone = telefone.slice(2);
}

const nome = row['Contato principal'] || 'Sem nome';
const titulo = telefone ? nome + ' | ' + telefone : nome;

const nomeEtapa = norm(row['Etapa do lead'] || '');
const stepId = STEP_IDS[nomeEtapa] || null;

if (!stepId) {
  console.log('AVISO: Etapa nao encontrada: "' + nomeEtapa + '"');
}

const tagIds = resolverTagIds(row['Lead tags'] || '');

return [{ json: {
  nome,
  titulo,
  telefone,
  tagIds,
  descricao: row['Nota 1'] || '',
  stepId
}}];

const contactResp = $input.item.json;
const lead = $('Preparar Dados do Lead').item.json;

const contactId = contactResp?.id || null;

const cardPayload = {
  stepId: lead.stepId,
  title: lead.titulo,
  description: lead.descricao || null,
  tagIds: lead.tagIds
};
if (contactId) cardPayload.contactIds = [contactId];

return [{ json: { ...lead, contactId, bodyString: JSON.stringify(cardPayload) } }];
